
import renderExcalidraw from '@org-press/block-excalidraw/wrapper';

export default function render(containerId) {
  const container = document.getElementById(containerId);
  if (!container) {
    console.error('[Excalidraw] Container not found:', containerId);
    return;
  }

  container.className = 'excalidraw-wrapper';
  container.style.cssText = 'position: relative; height: 350px;';

  try {
    const data = {
  "type": "excalidraw",
  "version": 2,
  "elements": [
    {
      "type": "rectangle",
      "id": "default-preset",
      "x": 50,
      "y": 50,
      "width": 200,
      "height": 250,
      "strokeColor": "#1971c2",
      "backgroundColor": "#e7f5ff",
      "fillStyle": "solid",
      "strokeWidth": 2,
      "roughness": 0,
      "roundness": { "type": 3 }
    },
    {
      "type": "text",
      "id": "default-title",
      "x": 90,
      "y": 60,
      "text": "defaultPlugins",
      "fontSize": 16,
      "strokeColor": "#1864ab",
      "fontFamily": 1
    },
    {
      "type": "text",
      "id": "default-items",
      "x": 70,
      "y": 95,
      "text": "domPlugin\njavascriptPlugin\ntypescriptPlugin\ncssPlugin\nserverPlugin",
      "fontSize": 14,
      "strokeColor": "#495057"
    },
    {
      "type": "rectangle",
      "id": "cli-preset",
      "x": 280,
      "y": 50,
      "width": 180,
      "height": 150,
      "strokeColor": "#e8590c",
      "backgroundColor": "#fff4e6",
      "fillStyle": "solid",
      "strokeWidth": 2,
      "roughness": 0,
      "roundness": { "type": 3 }
    },
    {
      "type": "text",
      "id": "cli-title",
      "x": 330,
      "y": 60,
      "text": "cliPlugins",
      "fontSize": 16,
      "strokeColor": "#d9480f",
      "fontFamily": 1
    },
    {
      "type": "text",
      "id": "cli-items",
      "x": 300,
      "y": 95,
      "text": "fmtPlugin\nlintPlugin\ntypeCheckPlugin",
      "fontSize": 14,
      "strokeColor": "#495057"
    },
    {
      "type": "rectangle",
      "id": "minimal-preset",
      "x": 280,
      "y": 220,
      "width": 180,
      "height": 80,
      "strokeColor": "#868e96",
      "backgroundColor": "#f1f3f5",
      "fillStyle": "solid",
      "strokeWidth": 2,
      "roughness": 0,
      "roundness": { "type": 3 }
    },
    {
      "type": "text",
      "id": "minimal-title",
      "x": 310,
      "y": 230,
      "text": "minimalPlugins",
      "fontSize": 16,
      "strokeColor": "#495057",
      "fontFamily": 1
    },
    {
      "type": "text",
      "id": "minimal-items",
      "x": 340,
      "y": 265,
      "text": "[ ]",
      "fontSize": 14,
      "strokeColor": "#868e96"
    }
  ],
  "appState": {
    "viewBackgroundColor": "#ffffff"
  }
}
;
    const mode = 'view';
    const filePath = undefined;
    const blockId = 'presets';

    renderExcalidraw(container, data, mode, filePath, blockId);
  } catch (err) {
    console.error('[Excalidraw] Failed to render diagram:', err);
    container.innerHTML = '<div style="color: red; padding: 1rem; border: 1px solid red;">Error rendering Excalidraw diagram: ' + err.message + '</div>';
  }
}
        